@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Sans:wght@400;500;600;700;800&display=swap');
:root{color-scheme:dark;--bg:#07141b;--panel:#0c1c24;--line:#1c3038;--muted:#89a0a6;--white:#f4f4ed;--lime:#d5f064;--blue:#36a9f5;--font-display:'Barlow Condensed',Impact,sans-serif;--font-body:'DM Sans',Arial,sans-serif}
*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:var(--bg);color:var(--white);font-family:var(--font-body)}body{min-height:100vh;background:radial-gradient(ellipse at 48% -30%,#183540 0,#0a1a21 47%,#07141b 78%)}button{font:inherit;color:inherit}.game-shell{max-width:1600px;margin:0 auto;padding:0 40px;min-height:100vh;display:flex;flex-direction:column}.topbar{height:82px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(164,201,204,.14);flex:none}.brand{display:flex;gap:12px;align-items:center;color:inherit;text-decoration:none}.brand-mark{width:37px;height:37px;border:1px solid #d5f064;display:grid;place-items:center;color:var(--lime);font:800 17px var(--font-display);letter-spacing:-1px;position:relative}.brand-mark span{font-size:10px;position:absolute;right:4px;top:3px}.brand-copy{display:grid;gap:2px}.brand-copy strong{font:800 17px var(--font-display);letter-spacing:1.6px}.brand-copy small{color:#7d9299;font-size:8px;letter-spacing:2px;font-weight:700}.track-name{display:flex;align-items:center;gap:10px;color:#a6b8b8;font-size:10px;letter-spacing:1.5px;font-weight:700}.track-name i{color:#526a70;font-style:normal}.live-dot,.status-pip{width:6px;height:6px;border-radius:100%;background:var(--lime);box-shadow:0 0 11px #d5f06488}.sound-button{background:none;border:1px solid #293e44;padding:8px 11px;display:flex;gap:8px;align-items:center;color:#abc0c0;cursor:pointer;font-size:10px;letter-spacing:1px}.sound-button:hover{border-color:var(--lime);color:var(--lime)}.sound-button>span:first-child{font-size:15px;color:var(--lime)}
.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:22px;margin-top:24px;flex:1;align-items:stretch;min-height:570px;max-height:calc(100vh - 151px)}.race-frame{position:relative;overflow:hidden;background:#15413b;border:1px solid #28434a;min-height:530px;isolation:isolate;box-shadow:0 20px 70px #0005}.race-frame canvas{position:absolute;inset:0;width:100%;height:100%;display:block}.frame-vignette{position:absolute;inset:0;pointer-events:none;z-index:1;box-shadow:inset 0 0 90px #06141877,inset 0 0 0 1px #ffffff08}.side-panel{padding:21px 20px 14px;background:linear-gradient(155deg,#10232a,#0a1a21);border:1px solid #20333a;display:flex;flex-direction:column;min-height:530px}.panel-topline{display:flex;align-items:center;gap:9px;color:#94a9a7;letter-spacing:2px;font-size:9px;font-weight:700}.panel-dot{width:5px;height:5px;border-radius:50%;background:#ef9c65}.side-panel h2{font:900 40px/.87 var(--font-display);letter-spacing:.3px;margin:18px 0 14px}.side-panel h2 em,.intro-overlay h1 em,.pause-panel h2 em,.finish-panel h2 em{font-style:normal;color:var(--lime)}.side-panel>p{font-size:11px;line-height:1.75;color:#9aafb1;margin:0 0 19px;max-width:215px}.track-facts{display:grid;grid-template-columns:1fr 1fr}.track-facts>div{display:grid;gap:5px}.track-facts>div+div{border-left:1px solid #2a4045;padding-left:16px}.track-facts span,.track-facts strong small{font-size:8px;letter-spacing:1.2px;color:#81989b;font-weight:700}.track-facts strong{font:700 22px var(--font-display);color:#eaf1de}.track-facts strong small{font:700 9px var(--font-body)}.side-divider{height:1px;background:#24393e;margin:17px 0 14px}.controls-heading{display:flex;justify-content:space-between;align-items:center;font-size:9px;letter-spacing:1.4px;font-weight:700}.controls-heading small{font-size:8px;color:#70868b;letter-spacing:1px}.key-guide{display:grid;gap:9px;margin-top:13px}.key-row{display:flex;align-items:center;gap:11px;color:#acbdbc;font-size:10px}.key-cluster{width:72px;display:flex;gap:3px;align-items:center}kbd{font:700 9px var(--font-body);color:#c3d0c8;min-width:20px;height:20px;display:inline-grid;place-items:center;background:#14272d;border:1px solid #30454a;border-bottom-width:2px;border-radius:3px}.key-cluster kbd:nth-child(2){color:var(--lime)}.key-cluster kbd:last-child:first-child{min-width:48px;font-size:8px}.tip-card{display:flex;gap:9px;align-items:flex-start;background:#172a2c;border:1px solid #2d4140;padding:10px;margin-top:16px}.tip-card>span{color:var(--lime);font-size:14px}.tip-card p{margin:0;color:#9bb0aa;font-size:9px;line-height:1.6}.tip-card strong{color:#d7e3cf;font-size:8px;letter-spacing:1px}.side-footer{margin-top:auto;padding-top:13px;display:flex;justify-content:space-between;color:#60777b;font-size:7px;letter-spacing:.7px;font-weight:700}.side-footer b{color:var(--lime);padding:0 3px}
.bottom-bar{height:48px;display:flex;align-items:center;justify-content:space-between;color:#71868b;font-size:8px;letter-spacing:1px;font-weight:700;flex:none}.footer-location,.footer-center,.footer-version{display:flex;align-items:center;gap:8px}.footer-location i{font-style:normal;color:#40575e}.location-icon{color:var(--lime);font-size:14px}.footer-center{color:#8aa09e}.flag-icon{color:#d5f064}.footer-version{gap:7px}.footer-version .status-pip{width:5px;height:5px}.footer-version b{color:#9db1ad}.footer-sep{color:#3d535a}
.screen-overlay{position:absolute;z-index:4;inset:0}.intro-overlay{background:linear-gradient(90deg,rgba(6,18,23,.95) 0%,rgba(7,20,25,.89) 39%,rgba(8,21,28,.26) 72%,rgba(6,18,24,.25) 100%),linear-gradient(0deg,#07141b88,transparent 30%,#06151b33);display:flex;align-items:center;padding:47px 6.2% 55px}.intro-copy{position:relative;z-index:2;width:53%;max-width:515px}.season-tag{display:inline-flex;align-items:center;gap:8px;color:#c1d6ba;font-weight:700;letter-spacing:1.6px;font-size:9px}.season-tag span{width:6px;height:6px;background:var(--lime);border-radius:50%;box-shadow:0 0 12px #d5f06477}.kicker{color:#9fb3ab;font-size:9px;letter-spacing:2.1px;font-weight:700;margin:26px 0 8px}.intro-overlay h1{font:900 clamp(46px,6.6vw,82px)/.82 var(--font-display);letter-spacing:-1px;margin:0;color:#f5f5ec}.intro-overlay h1 em{display:inline-block;margin-top:8px}.intro-description{font-size:12px;line-height:1.7;color:#b1bfba;max-width:350px;margin:21px 0 18px}.intro-meta{display:flex;align-items:center;gap:13px;color:#91a4a0;font-size:8px;letter-spacing:1.1px;font-weight:700;margin-bottom:23px}.intro-meta b{font:700 14px var(--font-display);color:var(--lime);margin-right:4px}.intro-meta i{width:3px;height:3px;background:#5d7375;border-radius:100%}.primary-button{display:flex;align-items:center;justify-content:space-between;gap:22px;min-width:201px;background:var(--lime);border:0;color:#18221b;padding:13px 15px 13px 18px;font:800 11px var(--font-body);letter-spacing:1px;cursor:pointer;transition:background .16s,transform .16s}.primary-button b{font-size:17px;font-weight:500;line-height:10px}.primary-button:hover{background:#e5ff83;transform:translateY(-2px)}.keyboard-hint{display:block;color:#6f8587;font-size:8px;letter-spacing:1.2px;margin-top:12px}.keyboard-hint kbd,.pause-panel kbd{height:17px;min-width:39px;font-size:7px;margin-left:4px}.hero-car-wrap{position:absolute;right:1.5%;top:4%;bottom:4%;width:48%;display:flex;align-items:center;justify-content:center;pointer-events:none}.hero-car{position:relative;z-index:1;width:100%;height:100%;object-fit:contain;filter:drop-shadow(0 26px 25px #0009);mix-blend-mode:screen;mask-image:radial-gradient(ellipse 75% 62% at 52% 54%,#000 38%,#000d 64%,transparent 100%)}.car-glow{position:absolute;width:69%;height:30%;top:43%;left:18%;background:#087be1;filter:blur(62px);opacity:.28;transform:rotate(-14deg)}.car-caption{position:absolute;z-index:2;bottom:10%;right:9%;display:grid;gap:3px;text-align:right}.car-caption span{color:#d5f064;font-size:8px;font-weight:700;letter-spacing:1.5px}.car-caption strong{font:800 21px var(--font-display);letter-spacing:1px}.car-caption small{font-size:7px;color:#9caeb0;letter-spacing:1.2px}.hero-spark{position:absolute;right:5%;top:14%;font:900 31px var(--font-display);color:#d5f064;letter-spacing:-4px;transform:rotate(-23deg)}.intro-bottom{position:absolute;bottom:20px;left:6.2%;right:6.2%;display:flex;align-items:center;gap:11px;color:#819798;font-size:8px;letter-spacing:1px;font-weight:700}.intro-bottom div{height:1px;width:42px;background:#566d6f}.intro-bottom span:last-child{margin-left:auto}
.race-hud{position:absolute;z-index:2;inset:17px 18px auto;display:flex;align-items:flex-start;gap:8px;pointer-events:none}.race-hud[hidden],.screen-overlay[hidden],.countdown[hidden]{display:none!important}.hud-card{min-width:93px;padding:8px 10px 9px;background:#091b20d9;border:1px solid #a9c1b322;box-shadow:0 4px 15px #0003;display:grid;gap:3px}.eyebrow{font-size:7px;letter-spacing:1.4px;font-weight:700;color:#9db4ad}.hud-card strong{font:700 19px var(--font-display);letter-spacing:.4px}.hud-card strong i{font-style:normal;color:#728783;font-size:12px;padding:0 3px}.lap-progress{height:2px;background:#415b56;margin-top:2px}.lap-progress b{height:100%;display:block;width:0;background:var(--lime)}.timer-card{min-width:117px}.timer-card strong{font:700 16px var(--font-display);letter-spacing:.5px}.timer-card small,.position-card small{font-size:7px;letter-spacing:1px;color:#90a49c}.position-card strong{color:var(--lime)}.speed-card{margin-left:auto;margin-top:0;width:95px;padding:8px 10px;background:#091b20d9;border:1px solid #a9c1b322;text-align:right}.speed-number{display:flex;align-items:baseline;justify-content:flex-end;gap:5px}.speed-number strong{font:800 30px/.9 var(--font-display);letter-spacing:.5px}.speed-number span{font-size:7px;color:#9db4ad;letter-spacing:1px}.speed-meter{height:3px;background:#293f3c;margin:8px 0 5px}.speed-meter b{display:block;width:0;height:100%;background:var(--lime);transition:width .12s}.gear-label{font-size:7px;letter-spacing:1px;color:#9db4ad}.gear-label b{color:var(--lime);font-size:10px}.countdown{position:absolute;z-index:5;left:50%;top:48%;transform:translate(-50%,-50%);display:grid;justify-items:center;text-shadow:0 5px 25px #000}.countdown span{font-size:9px;letter-spacing:3px;font-weight:800;color:#d5f064}.countdown strong{font:900 102px/.95 var(--font-display);color:#fff;animation:count-pop .75s ease-out}@keyframes count-pop{0%{transform:scale(1.55);opacity:.2}35%{transform:scale(1)}100%{opacity:1}}
.pause-overlay,.finish-overlay{background:#061319c9;backdrop-filter:blur(5px);display:grid;place-items:center}.pause-panel,.finish-panel{width:min(380px,88%);background:linear-gradient(145deg,#10252c,#09181e);border:1px solid #3b5555;padding:34px 38px;text-align:center;box-shadow:0 20px 70px #0008}.pause-icon{display:inline-grid;place-items:center;border:1px solid #4f6764;width:32px;height:32px;color:var(--lime);font-size:15px}.pause-panel .kicker,.finish-panel .kicker{margin:17px 0 8px}.pause-panel h2,.finish-panel h2{font:900 47px/.82 var(--font-display);margin:0 0 13px}.pause-panel>p:not(.kicker){font-size:11px;color:#a5b7b1;margin:0 0 20px}.pause-panel .primary-button,.finish-panel .primary-button{width:100%;justify-content:space-between}.text-button{display:block;margin:13px auto 0;background:none;border:0;color:#91a7a1;font-size:9px;font-weight:700;letter-spacing:1px;cursor:pointer}.text-button span{color:var(--lime);font-size:14px;margin-left:4px}.text-button:hover{color:#e4eedb}.pause-panel>small{display:block;margin-top:20px;color:#6e8586;font-size:8px}.finish-panel .season-tag{justify-content:center}.finish-panel h2{font-size:59px;margin-top:7px}.finish-stats{display:grid;grid-template-columns:1fr 1fr;text-align:left;border-top:1px solid #2e4445;border-bottom:1px solid #2e4445;padding:12px 0;margin:20px 0}.finish-stats div+div{border-left:1px solid #2e4445;padding-left:17px}.finish-stats small{display:block;color:#8da39c;letter-spacing:1px;font-size:7px;margin-bottom:4px}.finish-stats strong{font:700 23px var(--font-display);color:#e9f1e3}.toast{position:absolute;z-index:6;left:50%;bottom:20px;transform:translate(-50%,20px);padding:9px 14px;background:#0a1b20;border:1px solid #53675a;color:var(--lime);font-size:9px;font-weight:700;letter-spacing:.8px;opacity:0;transition:.2s;pointer-events:none;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.touch-controls{display:none}
@media(max-width:1050px){.game-shell{padding:0 24px}.game-layout{grid-template-columns:minmax(0,1fr) 225px;gap:14px}.side-panel{padding:17px 15px}.side-panel h2{font-size:36px}.intro-overlay{padding-left:5%}.intro-overlay h1{font-size:clamp(48px,6vw,70px)}.hero-car-wrap{width:48%;right:0}}
@media(max-width:760px){.game-shell{padding:0 12px;min-height:100svh}.topbar{height:62px}.brand-mark{width:32px;height:32px}.brand-copy strong{font-size:15px}.track-name{font-size:8px;gap:6px}.track-name span:last-child,.track-name i{display:none}.sound-button{padding:6px 8px}.sound-label{display:none}.game-layout{display:block;margin-top:12px;min-height:0;max-height:none;flex:none}.race-frame{height:min(69svh,620px);min-height:410px}.side-panel{display:none}.bottom-bar{height:37px;font-size:7px}.footer-center{display:none}.footer-version{font-size:7px}.intro-overlay{align-items:flex-start;padding:34px 6% 46px;background:linear-gradient(90deg,#061319eb 0%,#07141bdc 52%,#07141b44 100%),linear-gradient(0deg,#07141b77,transparent 40%)}.intro-copy{width:75%;max-width:420px}.season-tag{font-size:8px}.intro-overlay .kicker{margin-top:24px;font-size:8px}.intro-overlay h1{font-size:clamp(48px,10vw,70px)}.intro-description{font-size:10px;max-width:275px;margin:16px 0}.intro-meta{gap:7px;font-size:7px;margin-bottom:17px}.intro-meta b{font-size:12px}.primary-button{min-width:183px;padding:11px 13px 11px 15px;font-size:10px}.hero-car-wrap{right:-16%;top:30%;bottom:0;width:79%;height:67%;opacity:.82}.hero-car{mask-image:radial-gradient(ellipse 80% 64% at 53% 54%,#000 35%,#000d 63%,transparent 100%)}.car-caption{right:20%;bottom:13%}.hero-spark{right:18%;top:36%}.intro-bottom{left:6%;right:6%;bottom:14px}.intro-bottom span:last-child{font-size:7px}.race-hud{inset:9px 9px auto;gap:5px}.hud-card{min-width:66px;padding:6px 7px}.eyebrow{font-size:6px}.hud-card strong{font-size:16px}.timer-card{min-width:93px}.timer-card strong{font-size:14px}.timer-card small,.position-card small{font-size:6px}.position-card{min-width:74px}.speed-card{width:77px;padding:6px 7px}.speed-number strong{font-size:25px}.speed-number span{font-size:6px}.speed-meter{margin:6px 0 4px}.gear-label{font-size:6px}.touch-controls{display:flex;position:fixed;z-index:8;left:18px;right:18px;bottom:max(18px,env(safe-area-inset-bottom));justify-content:space-between;pointer-events:none}.touch-steer,.touch-pedals{display:flex;align-items:flex-end;gap:9px;pointer-events:auto}.touch-controls button{border:1px solid #d5f06475;background:#09191dbb;color:#eff7e4;backdrop-filter:blur(5px);width:53px;height:53px;border-radius:50%;font:700 22px var(--font-display);touch-action:none;user-select:none;-webkit-user-select:none}.touch-controls button:active,.touch-controls button.pressed{background:#d5f064;color:#13201a}.touch-pedals button{font:700 8px var(--font-body);letter-spacing:.7px}.touch-pedals .touch-go{background:#d5f064;color:#13201a;font-size:18px}.countdown{top:43%}.countdown strong{font-size:78px}.pause-panel,.finish-panel{padding:27px 25px}.finish-panel h2{font-size:52px}}
@media(max-width:420px){.brand-copy small{font-size:7px}.track-name{display:none}.race-frame{height:68svh;min-height:385px}.intro-overlay{padding-top:27px}.intro-overlay h1{font-size:48px}.intro-description{max-width:230px}.intro-meta{gap:5px}.hero-car-wrap{width:90%;right:-24%;top:33%;height:63%;opacity:.74}.car-caption{right:25%;bottom:13%}.intro-bottom{font-size:7px}.footer-location{gap:5px}.footer-version{gap:4px}.speed-card{width:68px}.position-card{min-width:65px}.timer-card{min-width:85px}.hud-card{min-width:60px}}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{scroll-behavior:auto!important;animation-duration:.01ms!important;transition-duration:.01ms!important}}

(() => {
  'use strict';
  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const W = 1200, H = 760, ROAD = 104, LAPS = 3;
  const $ = (id) => document.getElementById(id);
  const ui = {
    intro: $('introOverlay'), hud: $('raceHud'), pause: $('pauseOverlay'), finish: $('finishOverlay'),
    start: $('startButton'), resume: $('resumeButton'), restart: $('restartButton'), again: $('againButton'), menu: $('menuButton'),
    countdown: $('countdown'), countNumber: $('countNumber'), lap: $('lapCurrent'), lapBar: $('lapBar'), time: $('raceTime'),
    best: $('bestTime'), pos: $('positionNow'), posLabel: $('positionLabel'), speed: $('speedValue'), meter: $('speedMeter'),
    gear: $('gearValue'), finishTitle: $('finishTitle'), finishKicker: $('finishKicker'), finishPos: $('finishPosition'),
    finishTime: $('finishTime'), toast: $('toast'), record: $('recordValue'), sound: $('soundToggle'), soundIcon: $('soundIcon')
  };
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const mod = (v, n) => ((v % n) + n) % n;
  const lerp = (a, b, t) => a + (b - a) * t;
  const fmtTime = (t) => `${String(Math.floor(t / 60)).padStart(2, '0')}:${String(Math.floor(t % 60)).padStart(2, '0')}.${String(Math.floor((t * 100) % 100).padStart ? 0 : 0)}`;
  function timeText(t) { const mm = Math.floor(t / 60), ss = Math.floor(t % 60), cs = Math.floor((t * 100) % 100); return `${String(mm).padStart(2,'0')}:${String(ss).padStart(2,'0')}.${String(cs).padStart(2,'0')}`; }

  const anchors = [[210,180],[330,132],[470,128],[610,160],[735,146],[865,155],[970,210],[1030,300],[1033,385],[978,455],[882,487],[804,545],[752,615],[630,637],[516,603],[438,540],[345,516],[250,492],[170,442],[132,365],[137,288],[164,222]];
  function catmull(p0,p1,p2,p3,t) {
    const t2=t*t,t3=t2*t;
    return {x:.5*((2*p1[0])+(-p0[0]+p2[0])*t+(2*p0[0]-5*p1[0]+4*p2[0]-p3[0])*t2+(-p0[0]+3*p1[0]-3*p2[0]+p3[0])*t3), y:.5*((2*p1[1])+(-p0[1]+p2[1])*t+(2*p0[1]-5*p1[1]+4*p2[1]-p3[1])*t2+(-p0[1]+3*p1[1]-3*p2[1]+p3[1])*t3)};
  }
  const track=[];
  const steps=48;
  for(let i=0;i<anchors.length;i++) for(let j=0;j<steps;j++) track.push(catmull(anchors[mod(i-1,anchors.length)],anchors[i],anchors[(i+1)%anchors.length],anchors[(i+2)%anchors.length],j/steps));
  let trackLength=0;
  for(let i=0;i<track.length;i++){const a=track[i],b=track[(i+1)%track.length];a.distance=trackLength;a.tangent=Math.atan2(b.y-a.y,b.x-a.x);trackLength+=Math.hypot(b.x-a.x,b.y-a.y);}
  const closest=(x,y)=>{let best=Infinity,at=0;for(let i=0;i<track.length;i++){const p=track[i],d=(p.x-x)**2+(p.y-y)**2;if(d<best){best=d;at=i;}}return {index:at,point:track[at],distance:Math.sqrt(best),along:track[at].distance};};
  function sampleAt(s){let target=mod(s,trackLength),lo=0,hi=track.length-1;while(lo<hi){const m=(lo+hi)>>1;if(track[m].distance<target)lo=m+1;else hi=m;}const i=mod(lo-1,track.length),a=track[i],b=track[(i+1)%track.length],span=(b.distance>=a.distance?b.distance:trackLength-a.distance+b.distance)||1,t=mod(target-a.distance,trackLength)/span;return {x:lerp(a.x,b.x,t),y:lerp(a.y,b.y,t),angle:Math.atan2(b.y-a.y,b.x-a.x)};}

  let seed=87321;function random(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;}
  const trees=[];
  for(let y=42;y<H-30;y+=49)for(let x=34;x<W-20;x+=57){const px=x+(random()-.5)*24,py=y+(random()-.5)*22;if(closest(px,py).distance>ROAD*.5+49&&random()>.29)trees.push({x:px,y:py,r:8+random()*8,h:random()});}
  const grassDots=[];for(let i=0;i<1250;i++)grassDots.push({x:random()*W,y:random()*H,r:.4+random()*1.25,a:.035+random()*.1});
  const buildings=[{x:940,y:72,w:120,h:48,c:'#809392'},{x:58,y:520,w:92,h:47,c:'#748b80'},{x:966,y:610,w:135,h:52,c:'#8c8d78'}];
  function resize(){const dpr=Math.min(window.devicePixelRatio||1,2),r=canvas.getBoundingClientRect();canvas.width=Math.max(1,Math.round(r.width*dpr));canvas.height=Math.max(1,Math.round(r.height*dpr));}
  new ResizeObserver(resize).observe(canvas);window.addEventListener('resize',resize);resize();
  function roundedRect(c,x,y,w,h,r){c.beginPath();c.roundRect(x,y,w,h,r);}
  function drawTrees(){for(const b of buildings){ctx.fillStyle='#192e2a';ctx.fillRect(b.x+5,b.y+7,b.w,b.h);ctx.fillStyle=b.c;ctx.fillRect(b.x,b.y,b.w,b.h);ctx.fillStyle='#adad8b';ctx.fillRect(b.x+8,b.y+8,b.w-16,6);ctx.fillStyle='#506b65';for(let i=0;i<5;i++)ctx.fillRect(b.x+12+i*20,b.y+23,10,14);}
